import{NOT_AN_AGENT_MESSAGE}from"./preconditions.js";import{isEveProject,listAuthoredChannels}from"#setup/scaffold/index.js";async function runChannelsListCommand(t,n,r){if(!await isEveProject(n)){t.error(NOT_AN_AGENT_MESSAGE),process.exitCode=1;return}let i=await listAuthoredChannels(n);if(r.json){t.log(JSON.stringify({channels:i},null,2));return}if(i.length===0){t.log("No channels defined. Run `eve add <channel>` to add one.");return}for(let e of i)t.log(e)}export{runChannelsListCommand};